7	pub(crate) struct FormatMdHardLine {
8	    print_mode: TextPrintMode,
9	}
10	impl FormatNodeRule<MdHardLine> for FormatMdHardLine {
11	    fn fmt_fields(&self, node: &MdHardLine, f: &mut MarkdownFormatter) -> FormatResult<()> {
12	        let token = node.value_token()?;
13	
14	        if self.print_mode.is_pristine() {
15	            return format_verbatim_node(node.syntax()).fmt(f);
16	        }
17	
18	        let text_content = token.text();
19	
20	        if text_content.trim_end().ends_with('\\') {
21	            // Preserve backslash form
22	            write!(
23	                f,
24	                [
25	                    format_removed(&token),
26	                    text("\\", token.text_range().start()),
27	                    hard_line_break()
28	                ]
29	            )
30	        } else {
31	            // Given two or more spaces in MdHardLine, only two spaces has semantic meaning
32	            // so we are adding back two spaces as required by the spec
33	            // https://spec.commonmark.org/0.31.2/#hard-line-break
34	            write!(
35	                f,
36	                [
37	                    format_removed(&token),
38	                    text("  ", token.text_range().start()),
39	                    hard_line_break(),
40	                ]
41	            )
42	        }
43	    }
44	}
