19	impl FormatNodeRule<MdParagraph> for FormatMdParagraph {
20	    fn fmt_fields(&self, node: &MdParagraph, f: &mut MarkdownFormatter) -> FormatResult<()> {
21	        let MdParagraphFields { list, hard_line } = node.as_fields();
22	        write!(
23	            f,
24	            [list
25	                .format()
26	                .with_options(FormatMdFormatInlineItemListOptions {
27	                    print_mode: self.trim_mode
28	                })]
29	        )?;
30	        if let Some(hard_line) = hard_line {
31	            write!(f, [hard_line.format()])?;
32	        }
33	        Ok(())
34	    }
35	}
