            // so we are adding back two spaces as required by the spec
            // https://spec.commonmark.org/0.31.2/#hard-line-break
            write!(
                f,
                [
                    format_removed(&token),
                    text("  ", token.text_range().start()),
                    hard_line_break(),
                ]
            )
        }
    }
}

